it('should write to the latest control when control changes', async () => {
  type FormValues = {
    test: string;
  };

  let formA: UseFormReturn<FormValues>;
  let formB: UseFormReturn<FormValues>;

  const Input = ({ control }: { control: Control<FormValues> }) => {
    const { field } = useController({
      control,
      name: 'test',
      defaultValue: '',
    });

    return <input {...field} />;
  };

  const App = () => {
    formA = useForm<FormValues>({
      defaultValues: { test: 'value-a' },
      mode: 'onBlur',
    });
    formB = useForm<FormValues>({
      defaultValues: { test: 'value-b' },
      mode: 'onBlur',
    });
    const [useFormB, setUseFormB] = useState(false);

    return (
      <div>
        <Input control={useFormB ? formB.control : formA.control} />
        <button type="button" onClick={() => setUseFormB(true)}>
          switch control
        </button>
      </div>
    );
  };

  render(<App />);

  fireEvent.click(screen.getByRole('button', { name: 'switch control' }));
  fireEvent.click(screen.getByRole('button', { name: 'change field' }));
  fireEvent.click(screen.getByRole('button', { name: 'blur field' }));

  await waitFor(() => {
    expect(formA.getValues('test')).toBe('value-a');
    expect(formB.getValues('test')).toBe('typed-in-b');
    expect(formA.formState.touchedFields.test).toBeUndefined();
    expect(formB.formState.touchedFields.test).toBe(true);
  });
});

